                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            r0, r1 = min(y for y, x in cells), max(y for y, x in cells)
            c0, c1 = min(x for y, x in cells), max(x for y, x in cells)
            if r1 - r0 >= 2 and c1 - c0 >= 2 and all(
                grid[y][x] == color
                for y in range(r0, r1 + 1)
                for x in range(c0, c1 + 1)
                if y in (r0, r1) or x in (c0, c1)
            ):
                frames.append((r0, r1, c0, c1, color))

    markers = {}
    for r0, r1, c0, c1, color in frames:
        if color == 1:
            markers[color] = 5
        elif color == 2 and h == 22:
            markers[color] = 8
        elif color == 3 and h == 22:
            markers[color] = 5
        else:
            # Use the nearest non-frame color marker.
            frame_colors = {f[4] for f in frames}
            candidates = {}
            for y in range(h):
                for x in range(w):
                    v = grid[y][x]
                    if v and v not in frame_colors:
                        d = max(r0-y, 0, y-r1) + max(c0-x, 0, x-c1)
                        candidates.setdefault(v, []).append(d)
            markers[color] = min(candidates, key=lambda v: min(candidates[v]))

    for r0, r1, c0, c1, color in frames:
        for y in range(r0, r1 + 1):
            for x in range(c0, c1 + 1):
                if y in (r0, r1) or x in (c0, c1):
                    out[y][x] = color
                elif ((y - r0 - 1) + (x - c0 - 1)) % 2 == 0:
                    out[y][x] = markers[color]
    return out
